import { pgTable, uuid, text, real, integer, timestamp } from "drizzle-orm/pg-core";
import { manufacturingOrders } from "./manufacturing-orders.js";
import { workCenters } from "./work-centers.js";

/**
 * MODEL: machine_production_logs
 * PURPOSE: Decoupled time-block logs recording shift output, good units, and scrap generated by machines.
 * EXAMPLE: Operator "AMH-0001" on "PRESS-01" produced 250.0 meters with 4.5 meters scrap during Morning Shift.
 */
export const machineProductionLogs = pgTable("machine_production_logs", {
  id: uuid("id").primaryKey().defaultRandom(), // Unique identifier
  manufacturingOrderId: uuid("manufacturing_order_id").notNull().references(() => manufacturingOrders.id), // Work order reference ID
  workCenterCode: text("work_center_code").notNull().references(() => workCenters.code), // Machine code, e.g., "PRESS-01"
  operatorId: text("operator_id").notNull(), // Employee ID, e.g., "AMH-0001"
  shiftName: text("shift_name").notNull(), // Shift work block, e.g., "Morning_Shift", "Night_Shift"
  startTime: timestamp("start_time").notNull(), // Log block start timestamp
  endTime: timestamp("end_time").notNull(), // Log block end timestamp
  durationMinutes: integer("duration_minutes").notNull(), // Elapsed duration in minutes, e.g., 240
  outputQuantity: real("output_quantity").notNull(), // Good units produced in block, e.g., 250.0
  outputUnit: text("output_unit").notNull(), // Unit of measure, e.g., "meters", "pieces"
  scrapQuantity: real("scrap_quantity").default(0.0).notNull(), // Defective units generated, e.g., 4.5
  notes: text("notes"), // Remarks, e.g., "Minor cooling line stutter during mid-shift run"
  createdAt: timestamp("created_at").defaultNow().notNull(), // Record creation timestamp
});